/**
 * Unit tests for the UserWebauthnCredentialSignCountAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class UserWebauthnCredentialSignCountAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getSignCount returns null on a freshly created holder.
     */
    public function testSignCountNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithUserWebauthnCredentialSignCountAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isSignCountAssigned());
        $this->assertNull($holder->getSignCount());
    }
}
