    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedSignCountRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultSignCount();
    }
}
